-- Metadata only; run inside a caller-owned read-only transaction on STAGING.
-- No user content, credentials, function bodies or cron commands are returned.
select jsonb_build_object(
 'tables',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity)order by n.nspname,c.relname)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','spot_private')and c.relkind in('r','p','v')),'[]'),
 'columns',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||'.'||a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))order by n.nspname,c.relname,a.attnum)from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in('public','spot_private')and c.relkind in('r','p','v')and a.attnum>0 and not a.attisdropped),'[]'),
 'constraints',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||'.'||k.conname,'definition',pg_get_constraintdef(k.oid,true))order by n.nspname,c.relname,k.conname)from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','spot_private')),'[]'),
 'indexes',coalesce((select jsonb_agg(jsonb_build_object('key',schemaname||'.'||indexname,'definition',indexdef)order by schemaname,indexname)from pg_indexes where schemaname in('public','spot_private')),'[]'),
 'triggers',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||'.'||t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled)order by n.nspname,c.relname,t.tgname)from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in('public','spot_private','auth')),'[]'),
 'policies',coalesce((select jsonb_agg(jsonb_build_object('key',schemaname||'.'||tablename||'.'||policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'qual',qual,'with_check',with_check)order by schemaname,tablename,policyname)from pg_policies where schemaname in('public','spot_private','storage')),'[]'),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','source_md5',md5(p.prosrc),'return_type',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'language',l.lanname,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'))order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in('public','spot_private')and p.prokind='f'and not exists(select 1 from pg_depend e where e.classid='pg_proc'::regclass and e.objid=p.oid and e.deptype='e')),'[]'),
 'relation_access',coalesce((select jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||':'||r.role,'select',has_table_privilege(r.role,c.oid,'SELECT'),'insert',has_table_privilege(r.role,c.oid,'INSERT'),'update',has_table_privilege(r.role,c.oid,'UPDATE'),'delete',has_table_privilege(r.role,c.oid,'DELETE'))order by n.nspname,c.relname,r.role)from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join(values('anon'),('authenticated'),('service_role'))r(role)where n.nspname in('public','spot_private')and c.relkind in('r','p','v')),'[]')
) as catalog;
